rule_yaml:
rules:
  - id: dubbo-npe-c1-r2
    languages:
      - java
    severity: ERROR
    message: >-
      A possibly-null value is used without a null guard: the URL component field
      'urlAddress' (left null by the no-arg constructor chain URL() /
      ServiceConfigURL() / URLBuilder()), the result of a nullable service-info
      lookup (getServiceInfo() / getValidServiceInfo(), which return null when no
      matching ServiceInfo exists), or a service path read from an invocation
      attachment (inv.getAttachments().get(PATH_KEY) /
      inv.getObjectAttachmentWithoutConvert(PATH_KEY)). The unguarded use throws
      a NullPointerException (the attachment case surfaces as a misleading NPE
      out of the service-key cache lookup). Guard the value before using it, e.g.
      if (x == null) return/throw ...; / if (x != null) { ... } /
      x == null ? ... : x.method().
    paths:
      exclude:
        - "**/src/test/**"
        - "**/test/**"
    patterns:
      - pattern-either:
          # (A) nullable service-info lookup result dereferenced directly
          - pattern: getServiceInfo(...).$M(...)
          - pattern: getValidServiceInfo(...).$M(...)
          # (B) nullable lookup result stored in a local, then dereferenced
          #     without any null guard (early return / if / ternary forms)
          - patterns:
              - pattern-inside: |
                  $TYPE $SI = $LOOKUP(...);
                  ...
              - metavariable-regex:
                  metavariable: $LOOKUP
                  regex: "(getServiceInfo|getValidServiceInfo)$"
              - pattern: $SI.$M(...)
              - pattern-not-inside: |
                  if (<... null == $SI ...>) {
                      ...
                  }
                  ...
              - pattern-not-inside: |
                  if (<... $SI == null ...>) {
                      ...
                  }
                  ...
              - pattern-not-inside: |
                  if (<... null == $SI ...>) return $X;
                  ...
              - pattern-not-inside: |
                  if (<... $SI == null ...>) return $X;
                  ...
              - pattern-not-inside: |
                  if (<... null != $SI ...>) {
                      ...
                  }
              - pattern-not-inside: |
                  if (<... $SI != null ...>) {
                      ...
                  }
              - pattern-not-inside: "null == $SI ? $A : $SI.$M(...)"
              - pattern-not-inside: "$SI == null ? $A : $SI.$M(...)"
              - pattern-not-inside: "null != $SI ? $SI.$M(...) : $A"
              - pattern-not-inside: "$SI != null ? $SI.$M(...) : $A"
          # (C) URL component field 'urlAddress' dereferenced unconditionally
          - patterns:
              - pattern-either:
                  - pattern: |
                      $T $V = urlAddress.$M(...);
                      return $R($V);
                  - pattern: |
                      return urlAddress.$M(...);
              - pattern-not-inside: |
                  if (<... urlAddress == null ...>) {
                      ...
                  }
              - pattern-not-inside: |
                  if (<... urlAddress != null ...>) {
                      ...
                  }
              - pattern-not-inside: |
                  urlAddress == null ? $A : $B
              - pattern-not-inside: |
                  urlAddress != null ? $A : $B
              - pattern-not-inside: |
                  if (...) {
                      ...
                  }
          # (D) nullable value read from an invocation attachment, then used
          #     unguarded to build a service key -> misleading NPE
          - patterns:
              - pattern-either:
                  - pattern: String $V = (String) $INV.$GETTER($KEY);
                  - pattern: String $V = $INV.$GETTER($KEY);
              - metavariable-regex:
                  metavariable: $GETTER
                  regex: (?i).*attachment.*
              - pattern-inside: |
                  $RET $M(...) {
                    ...
                    serviceKey(..., $V, ...);
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if (<... $V == null ...>) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if (<... null == $V ...>) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if (<... $V != null ...>) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if (<... null != $V ...>) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    $V == null ? $A : $B
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    $V != null ? $A : $B
                    ...
                  }
          # (D2) same defect via Map<String,String> attachment fetch
          - patterns:
              - pattern: String $V = $INV.getAttachments().get($KEY);
              - pattern-inside: |
                  $RET $M(...) {
                    ...
                    serviceKey(..., $V, ...);
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if (<... $V == null ...>) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if (<... null == $V ...>) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if (<... $V != null ...>) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    if (<... null != $V ...>) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    $V == null ? $A : $B
                    ...
                  }
              - pattern-not-inside: |
                  $RET $M(...) {
                    ...
                    $V != null ? $A : $B
                    ...
                  }
